player = 0;
base = 0x16d;
while (base < 0x17c) {
    int mapped_end = base + 5;
    for (action = 0, mapped = base;
         mapped < mapped_end;
         ++action, ++mapped) {
        if (key == mapped) {
            return provider->is_active(player, action);
        }
    }
    base = mapped;
    ++player;
}
return 0;

